// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 _value, address _target) public {
        vm.assume(_value > 0);
        vm.assume(_target != address(c));
        vm.assume(_target != address(0));
        vm.deal(address(c), _value);
        uint256 balanceBefore = address(c).balance;
        c.sendMoney(_target, _value);
        uint256 balanceAfter = address(c).balance;
        assertEq(balanceBefore - balanceAfter, _value);
    }
}
